import numpy as np
def gpipe(p, m):
    """GPipe-style grid: p stages, m microbatches, bwd slot = fwd slot.
    Returns utilization = busy cells / all cells."""
    T = 2 * (m + p - 1)                         # time slots
    grid = np.zeros((p, T), dtype=int)
    for s in range(p):
        for j in range(m):
            grid[s, s + j] = 1                  # forward of microbatch j
            grid[s, (m + p - 1) + (p - 1 - s) + j] = 2   # backward, reverse order
    return grid, (grid > 0).mean()
g, u = gpipe(4, 4)
for row in g: print("".join(".FB"[c] for c in row))
print("p=4,m=4 util %.1f%%  (formula m/(m+p-1) = %.1f%%)" % (100 * u, 100 * 4 / 7))
for p, m in [(4, 1), (8, 1), (8, 32), (16, 128)]:
    print(f"p={p:2d} m={m:3d}: util {100 * gpipe(p, m)[1]:5.1f}%  bubble {100 * (p - 1) / (m + p - 1):5.1f}%")
